top=8.dp)){Text("알림 접근 허용 설정")};OutlinedButton({runCatching{context.startActivity(Intent(Settings.ACTION_REQUEST_IGNORE_BATTERY_OPTIMIZATIONS,Uri.parse("package:${context.packageName}")))}},Modifier.fillMaxWidth().padding(top=8.dp)){Text("배터리 최적화 예외 요청")}};item{SectionTitle("오프라인 지도");Text("현재 마지막 위치 약 25km 반경을 줌 5~16으로 저장합니다.");Button({scope.launch{val p=graph.repository.latestTrackPoint()?:return@launch;val lat=25.0/111.0;val lon=25.0/(111.0*kotlin.math.cos(Math.toRadians(p.latitude)).coerceAtLeast(.2));graph.offlineMapManager.download("${p.latitude.format(2)}, ${p.longitude.format(2)} 주변",p.latitude+lat,p.longitude+lon,p.latitude-lat,p.longitude-lon)}},Modifier.fillMaxWidth().padding(vertical=8.dp)){Text("현재 위치 주변 오프라인 저장")};Text(when(val s=downloadState){OfflineDownloadState.Idle->"대기 중";is OfflineDownloadState.Downloading->"${s.name}: ${s.completed}/${s.required.takeIf{it>0}?:"?"} · ${s.bytes/1024/1024} MB";is OfflineDownloadState.Complete->"${s.name} 완료 · ${s.bytes/1024/1024} MB";is OfflineDownloadState.Failed->"실패: ${s.message}"})};items(regions,key={it.id}){r->Row(Modifier.fillMaxWidth().padding(vertical=8.dp),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(r.name);Text("${r.completedResources}/${r.requiredResources} · ${r.completedBytes/1024/1024} MB")};TextButton({graph.offlineMapManager.delete(r.id){refresh()}}){Text("삭제")}};HorizontalDivider()};item{SectionTitle("암호화 백업");Text(".nodemap은 PBKDF2-HMAC-SHA256 310,000회 + AES-256-GCM으로 암호화됩니다.");Row(Modifier.fillMaxWidth().padding(vertical=8.dp),horizontalArrangement=Arrangement.spacedBy(8.dp)){Button({backupAction=BackupAction.EXPORT}){Text("백업")};OutlinedButton({backupAction=BackupAction.RESTORE}){Text("복원")}};message?.let{Text(it)};Spacer(Modifier.height(32.dp))}};if(backupAction!=null)AlertDialog({backupAction=null;password=""},title={Text(if(backupAction==BackupAction.EXPORT)"백업 비밀번호" else "복원 비밀번호")},text={Column{if(backupAction==BackupAction.RESTORE)Text("복원하면 현재 기록을 백업 내