@Composable private fun SettingSwitch(title:String,description:String,checked:Boolean,onChange:(Boolean)->Unit){Row(Modifier.fillMaxWidth().padding(vertical=8.dp),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(title);Text(description)};Switch(checked,onChange)}};@Composable private fun PermissionRow(title:String,granted:Boolean,request:()->Unit){Row(Modifier.fillMaxWidth().padding(vertical=6.dp),verticalAlignment=Alignment.CenterVertically){Text(title,Modifier.weight(1f));if(granted)Text("허용됨")else Button(request){Text("허용")}}};@Composable private fun SectionTitle(title:String){Text(title,style=MaterialTheme.typography.headlineSmall,modifier=Modifier.padding(top=24.dp,bottom=8.dp))};private fun has(c:android.content.Context,p:String)=ContextCompat.checkSelfPermission(c,p)==PackageManager.PERMISSION_GRANTED;private fun Double.format(d:Int)="%.${d}f".format(this);private enum class BackupAction{EXPORT,RESTORE}
